import React, { useState, useEffect } from 'react';

const CommunityNetwork = () => {
  const [nearbyUsers, setNearbyUsers] = useState([]);
  const [safetyReports, setSafetyReports] = useState([]);
  const [showReportForm, setShowReportForm] = useState(false);
  const [newReport, setNewReport] = useState({ type: 'safe', description: '', anonymous: true });

  useEffect(() => {
    // Mock nearby users
    setNearbyUsers([
      { id: 1, name: 'Priya S.', distance: '0.2 km', status: 'safe', lastSeen: '2 min ago' },
      { id: 2, name: 'Anonymous User', distance: '0.5 km', status: 'safe', lastSeen: '5 min ago' },
      { id: 3, name: 'Kavya P.', distance: '0.8 km', status: 'alert', lastSeen: '1 min ago' }
    ]);

    // Mock safety reports
    setSafetyReports([
      { id: 1, type: 'safe', location: 'Metro Station', time: '10 min ago', votes: 5 },
      { id: 2, type: 'caution', location: 'Park Area', time: '30 min ago', votes: 3 },
      { id: 3, type: 'unsafe', location: 'Dark Alley', time: '1 hour ago', votes: 8 }
    ]);
  }, []);

  const submitReport = () => {
    if (!newReport.description.trim()) return;

    const report = {
      id: Date.now(),
      ...newReport,
      location: 'Current Location',
      time: 'Just now',
      votes: 1
    };

    setSafetyReports([report, ...safetyReports]);
    setNewReport({ type: 'safe', description: '', anonymous: true });
    setShowReportForm(false);
    alert('✅ Safety report submitted successfully!');
  };

  const sendCommunityAlert = () => {
    if (window.confirm('🚨 Send emergency alert to nearby NIVRA users?')) {
      alert('🚨 Emergency alert sent to 12 nearby users!\n\n📍 Your location shared\n⏰ Help is on the way');
    }
  };

  const theme = {
    bg: '#f8f9fa',
    cardBg: '#ffffff',
    text: '#333333',
    subtext: '#666666',
    border: '#e9ecef'
  };

  return (
    <div style={{ padding: '20px', background: theme.bg, minHeight: '100vh' }}>
      <h2 style={{ color: theme.text, marginBottom: '20px', textAlign: 'center' }}>
        👥 Community Network
      </h2>

      {/* Emergency Alert Button */}
      <div style={{
        background: 'linear-gradient(135deg, #ff416c 0%, #ff4b2b 100%)',
        borderRadius: '15px',
        padding: '20px',
        marginBottom: '20px',
        textAlign: 'center'
      }}>
        <h3 style={{ margin: '0 0 10px 0', color: 'white', fontSize: '18px' }}>
          🚨 Community Emergency Alert
        </h3>
        <button
          onClick={sendCommunityAlert}
          style={{
            background: 'rgba(255,255,255,0.2)',
            color: 'white',
            border: '2px solid rgba(255,255,255,0.5)',
            padding: '12px 24px',
            borderRadius: '25px',
            fontSize: '16px',
            fontWeight: 'bold',
            cursor: 'pointer'
          }}
        >
          📢 Alert Nearby Users
        </button>
        <p style={{ margin: '10px 0 0 0', color: 'rgba(255,255,255,0.8)', fontSize: '12px' }}>
          Sends anonymous alert to NIVRA users within 1km
        </p>
      </div>

      {/* Nearby Users */}
      <div style={{
        background: theme.cardBg,
        borderRadius: '15px',
        padding: '20px',
        marginBottom: '20px',
        border: `1px solid ${theme.border}`
      }}>
        <h3 style={{ margin: '0 0 15px 0', color: theme.text }}>👥 Nearby NIVRA Users</h3>
        {nearbyUsers.map((user) => (
          <div key={user.id} style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: '12px',
            marginBottom: '10px',
            background: theme.bg,
            borderRadius: '10px',
            border: `1px solid ${theme.border}`
          }}>
            <div>
              <div style={{ fontWeight: '600', color: theme.text }}>{user.name}</div>
              <div style={{ fontSize: '12px', color: theme.subtext }}>
                📍 {user.distance} • {user.lastSeen}
              </div>
            </div>
            <div style={{
              background: user.status === 'safe' ? '#34c759' : user.status === 'alert' ? '#ff9500' : '#ff3b30',
              color: 'white',
              padding: '4px 8px',
              borderRadius: '12px',
              fontSize: '11px',
              textTransform: 'uppercase'
            }}>
              {user.status}
            </div>
          </div>
        ))}
        <p style={{ fontSize: '12px', color: theme.subtext, textAlign: 'center', margin: '10px 0 0 0' }}>
          🔒 All data is anonymized for privacy
        </p>
      </div>

      {/* Safety Reports */}
      <div style={{
        background: theme.cardBg,
        borderRadius: '15px',
        padding: '20px',
        marginBottom: '20px',
        border: `1px solid ${theme.border}`
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
          <h3 style={{ margin: 0, color: theme.text }}>📍 Safety Reports</h3>
          <button
            onClick={() => setShowReportForm(true)}
            style={{
              background: '#667eea',
              color: 'white',
              border: 'none',
              padding: '8px 12px',
              borderRadius: '8px',
              fontSize: '12px',
              cursor: 'pointer'
            }}
          >
            + Report
          </button>
        </div>

        {safetyReports.map((report) => (
          <div key={report.id} style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: '12px',
            marginBottom: '10px',
            background: theme.bg,
            borderRadius: '10px',
            border: `1px solid ${theme.border}`
          }}>
            <div>
              <div style={{ 
                display: 'flex', 
                alignItems: 'center', 
                gap: '8px',
                marginBottom: '4px'
              }}>
                <span style={{
                  background: report.type === 'safe' ? '#34c759' : 
                            report.type === 'caution' ? '#ff9500' : '#ff3b30',
                  color: 'white',
                  padding: '2px 6px',
                  borderRadius: '8px',
                  fontSize: '10px',
                  textTransform: 'uppercase'
                }}>
                  {report.type === 'safe' ? '✅ Safe' : 
                   report.type === 'caution' ? '⚠️ Caution' : '🚨 Unsafe'}
                </span>
                <span style={{ fontSize: '14px', fontWeight: '500', color: theme.text }}>
                  {report.location}
                </span>
              </div>
              <div style={{ fontSize: '12px', color: theme.subtext }}>
                {report.time} • 👍 {report.votes} votes
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Report Form Modal */}
      {showReportForm && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          background: 'rgba(0,0,0,0.5)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000
        }}>
          <div style={{
            background: 'white',
            borderRadius: '15px',
            padding: '20px',
            maxWidth: '350px',
            width: '90%'
          }}>
            <h3 style={{ margin: '0 0 15px 0', color: theme.text }}>📍 Report Safety Status</h3>

            <div style={{ marginBottom: '15px' }}>
              <label style={{ display: 'block', marginBottom: '8px', color: theme.text, fontSize: '14px' }}>
                Safety Level:
              </label>
              <select
                value={newReport.type}
                onChange={(e) => setNewReport({...newReport, type: e.target.value})}
                style={{
                  width: '100%',
                  padding: '10px',
                  border: `1px solid ${theme.border}`,
                  borderRadius: '8px',
                  fontSize: '14px'
                }}
              >
                <option value="safe">✅ Safe Area</option>
                <option value="caution">⚠️ Use Caution</option>
                <option value="unsafe">🚨 Unsafe Area</option>
              </select>
            </div>

            <div style={{ marginBottom: '15px' }}>
              <label style={{ display: 'block', marginBottom: '8px', color: theme.text, fontSize: '14px' }}>
                Description:
              </label>
              <textarea
                value={newReport.description}
                onChange={(e) => setNewReport({...newReport, description: e.target.value})}
                placeholder="Describe the situation..."
                style={{
                  width: '100%',
                  height: '80px',
                  padding: '10px',
                  border: `1px solid ${theme.border}`,
                  borderRadius: '8px',
                  fontSize: '14px',
                  resize: 'none'
                }}
              />
            </div>

            <div style={{ marginBottom: '20px' }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px' }}>
                <input
                  type="checkbox"
                  checked={newReport.anonymous}
                  onChange={(e) => setNewReport({...newReport, anonymous: e.target.checked})}
                />
                Submit anonymously
              </label>
            </div>

            <div style={{ display: 'flex', gap: '10px' }}>
              <button
                onClick={submitReport}
                style={{
                  flex: 1,
                  background: '#34c759',
                  color: 'white',
                  border: 'none',
                  padding: '12px',
                  borderRadius: '8px',
                  fontSize: '14px',
                  cursor: 'pointer'
                }}
              >
                Submit Report
              </button>
              <button
                onClick={() => setShowReportForm(false)}
                style={{
                  flex: 1,
                  background: theme.border,
                  color: theme.subtext,
                  border: 'none',
                  padding: '12px',
                  borderRadius: '8px',
                  fontSize: '14px',
                  cursor: 'pointer'
                }}
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CommunityNetwork;
